args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==2);od<-args[2]
suppressPackageStartupMessages(library(data.table));seeds<-c(9527,20260904,314159);ls<-lapply(seeds,function(s){d<-file.path(od,paste0("seed_",s));stopifnot(file.exists(file.path(d,"scavenge.done")));x<-fread(file.path(d,"SCAVENGE_CELLTYPE_SUMMARY.tsv"));stopifnot(all(x$random_seed==s));x})
all<-rbindlist(ls);stopifnot(nrow(all)==21,all(is.finite(all$P)|all$test_status=="NOT_TESTED_NO_CONNECTED_CELLS"),all(all$n_donors<=2));all[,FDR_global_21:=p.adjust(P,"BH",n=21)];all[,role:=ifelse(random_seed==9527,"PRIMARY_SEED","SEED_SENSITIVITY")]
all[,enrichment_ratio:=if(sum(n_enriched)>0)(n_enriched/pmax(n_cells,1))/(sum(n_enriched)/sum(n_cells)) else NA_real_,by=random_seed]
fwrite(all,file.path(od,"SCAVENGE_ALL_SEEDS_CELLTYPE.tsv"),sep="\t")
wide<-dcast(all,cell_cluster~random_seed,value.var=c("P","FDR","FDR_global_21","mean_TRS","n_enriched","n_cells","enrichment_ratio"));cons<-all[,.(n_seeds=.N,n_seeds_tested=sum(test_status=="TESTED_CONNECTED_CELLS"),n_seeds_FDR_lt05=sum(FDR<.05,na.rm=TRUE),n_seeds_global_FDR_lt05=sum(FDR_global_21<.05,na.rm=TRUE),min_mean_TRS=if(any(is.finite(mean_TRS)))min(mean_TRS,na.rm=TRUE) else NA_real_,max_mean_TRS=if(any(is.finite(mean_TRS)))max(mean_TRS,na.rm=TRUE) else NA_real_,all_seeds_enrichment_ratio_gt1=all(is.finite(enrichment_ratio)&enrichment_ratio>1)),by=cell_cluster];wide<-merge(wide,cons,by="cell_cluster");wide[,`:=`(scope="STRICT_CLONE_BENCHMARK_CORTEX",max_reference_donors=2)]
fwrite(wide,file.path(od,"SCAVENGE_CELLTYPE_SEED_STABILITY.tsv"),sep="\t")
pair<-list();for(i in 1:2)for(j in (i+1):3){a<-fread(file.path(od,paste0("seed_",seeds[i]),"SCAVENGE_CELL_LEVEL.tsv.gz"));b<-fread(file.path(od,paste0("seed_",seeds[j]),"SCAVENGE_CELL_LEVEL.tsv.gz"));x<-merge(a[is.finite(TRS),.(cell_id,TRS_a=TRS)],b[is.finite(TRS),.(cell_id,TRS_b=TRS)],by="cell_id");pair[[length(pair)+1]]<-data.table(seed_a=seeds[i],seed_b=seeds[j],n_identical_cells=nrow(x),Spearman_TRS=if(nrow(x)>2)cor(x$TRS_a,x$TRS_b,method="spearman") else NA_real_)}
fwrite(rbindlist(pair),file.path(od,"SCAVENGE_COMMON_CELL_TRS_CORRELATION.tsv"),sep="\t")
writeLines(c("Primary seed=9527. Seeds 20260904 and 314159 are sensitivity runs, not independent biological replications.","Global BH is also reported over all 21 cell-type/seed tests. Two healthy adult cortex donors do not become cell-count biological replication.","Changing peak/cell subsampling across seeds makes exact common-cell counts necessary for TRS concordance.","No fine-mapping, GWAS disease direction, DRG receptor localization, or disc-to-neuron causality follows from this cortical reference alone."),file.path(od,"SCAVENGE_INTERPRETATION_BOUNDARY.md"));writeLines(format(Sys.time(),tz="UTC"),file.path(od,"scavenge_all_seeds.done"))
